    }

    .status-message {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--success);
      font-weight: 700;
      text-align: center;
    }

    @media (max-width: 40rem) {
      .page-shell {
        padding-inline: 0.75rem;
      }

      header {
        padding-top: 1rem;
      }

      .card {
        border-radius: 1.25rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
