<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <div class="page-shell">
    <header>
      <p class="eyebrow">Account setup</p>
      <h1>Choose how updates reach you.</h1>
      <p class="hero-copy">Select the notification channel that works best for timely product updates and account messages.</p>
