            <p class="required-note" id="notification-help">Choose one option. This question is required.</p>

            <div class="radio-list">
              <label class="radio-option" for="notification-email">
                <input type="radio" id="notification-email" name="notificationPreference" value="Email" required>
                <span class="option-text">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input type="radio" id="notification-sms" name="notificationPreference" value="SMS" required>
                <span class="option-text">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input type="radio" id="notification-push" name="notificationPreference" value="Push Notifications" required>
                <span class="option-text">Push Notifications</span>
              </label>
            </div>

            <p class="error-message" id="notification-error" aria-live="assertive"></p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p class="status-message" id="form-status" aria-live="polite"></p>
      </form>
    </main>
  </div>

  <script>
    const form = document.querySelector("#notification-form");
    const errorMessage = document.querySelector("#notification-error");
    const statusMessage = document.querySelector("#form-status");
    const radioButtons = [...document.querySelectorAll("input[name='notificationPreference']")];

    function setInvalidState(message) {
