      event.preventDefault();

      const selectedPreference = form.elements.notificationPreference.value;

      if (!selectedPreference) {
        setInvalidState("Select Email, SMS, or Push Notifications before submitting.");
        radioButtons[0].focus();
        return;
      }

      clearInvalidState();
      statusMessage.textContent = `Preference saved: ${selectedPreference}.`;
    });
  </script>
