      background: var(--primary);
      border-radius: 999px;
      transform: translateY(-150%);
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .page-shell {
      width: min(100%, 68rem);
      margin: 0 auto;
      padding: 2rem 1rem;
