      padding: 0.95rem 1.25rem;
      color: #ffffff;
      background: var(--primary);
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: background-color 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--primary-hover);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .status-message {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--success);
      font-weight: 700;
      text-align: center;
    }

    @media (max-width: 40rem) {
      .page-shell {
        padding-inline: 0.75rem;
      }

      header {
        padding-top: 1rem;
      }

      .card {
        border-radius: 1.25rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .radio-option,
      button {
        border: 2px solid ButtonBorder;
      }

      .radio-option:has(input:checked) {
        border-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <div class="page-shell">
    <header>
      <p class="eyebrow">Account setup</p>
      <h1>Choose how updates reach you.</h1>
      <p class="hero-copy">Select the notification channel that works best for timely product updates and account messages.</p>
    </header>

    <main id="main-content">
      <form class="card" id="notification-form" novalidate>
        <div class="form-field">
          <fieldset class="form-field" aria-describedby="notification-help notification-error">
            <legend>How do you prefer to receive notifications? <span class="required-marker" aria-hidden="true">*</span></legend>
            <p class="required-note" id="notification-help">Choose one option. This question is required.</p>

            <div class="radio-list">
              <label class="radio-option" for="notification-email">
                <input type="radio" id="notification-email" name="notificationPreference" value="Email" required>
                <span class="option-text">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input type="radio" id="notification-sms" name="notificationPreference" value="SMS" required>
                <span class="option-text">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input type="radio" id="notification-push" name="notificationPreference" value="Push Notifications" required>
                <span class="option-text">Push Notifications</span>
              </label>
            </div>

            <p class="error-message" id="notification-error" aria-live="assertive"></p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p class="status-message" id="form-status" aria-live="polite"></p>
      </form>
    </main>
  </div>

  <script>
    const form = document.querySelector("#notification-form");
    const errorMessage = document.querySelector("#notification-error");
    const statusMessage = document.querySelector("#form-status");
    const radioButtons = [...document.querySelectorAll("input[name='notificationPreference']")];

    function setInvalidState(message) {
